TLM.f("Sancti/12-27",{"officium":"S. Joannis Apostoli et Evangelistæ","rule":["Gloria","Credo","Prefatio=Nat"],"sections":{"Introitus":[{"k":"ref","la":"Eccli 15:5"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"macro","name":"Gloria"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Ecclésiam tuam, Dómine, benígnus illústra: ut, beáti Joánnis Apóstoli tui et Evangelístæ illumináta doctrínis, ad dona pervéniat sempitérna."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Lectio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 15:1-6"},{"k":"text","la":"Qui timet Deum, fáciet bona: et qui cóntinens est justítiæ, apprehéndet illam, et obviábit illi quasi mater honorificáta. Cibábit illum pane vitæ et intelléctus, et aqua sapiéntiæ salutáris potábit illum: et firmábitur in illo, et non flectétur: et continébit illum, et non confundétur: et exaltábit illum apud próximos suos, et in médio ecclésiæ apériet os ejus, et adimplébit illum spíritu sapiéntiæ et intelléctus, et stola glóriæ véstiet illum. Jucunditátem et exsultatiónem thesaurizábit super illum, et nómine ætérno hereditábit illum, Dóminus, Deus noster."}],"Graduale":[{"k":"ref","la":"Joann 21:23; 21:19"},{"k":"text","la":"Exiit sermo inter fratres, quod discípulus ille non móritur: et non dixit Jesus: Non móritur,"},{"k":"text","la":"Sed: Sic eum volo manére, donec véniam: tu me séquere.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Joann 21:24"},{"k":"text","la":"Hic est discípulus ille, qui testimónium pérhibet de his: et scimus, quia verum est testimónium ejus. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Joann 21:24"},{"k":"text","la":"Hic est discípulus ille, qui testimónium pérhibet de his: et scimus, quia verum est testimónium ejus."},{"k":"ref","la":"Ps 91:13"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secundum Joánnem"},{"k":"ref","la":"Joann 21:19-24"},{"k":"text","la":"In illo témpore: Dixit Jesus Petro: Séquere me. Convérsus Petrus vidit illum discípulum, quem diligébat Jesus, sequéntem, qui et recúbuit in cena super pectus ejus, et dixit: Dómine, quis est qui tradet te ? Hunc ergo cum vidísset Petrus, dixit Jesu: Dómine, hic autem quid? Dicit ei Jesus: Sic eum volo manére, donec véniam, quid ad te? tu me séquere. Exiit ergo sermo iste inter fratres, quia discípulus ille non móritur. Et non dixit ei Jesus: Non móritur; sed: Sic eum volo manére, donec véniam: quid ad te? Hic est discípulus ille, qui testimónium pérhibet de his, et scripsit hæc: et scimus, quia verum est testimónium ejus."}],"Offertorium":[{"k":"ref","la":"Ps 91:13"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus, quæ in Líbano est, multiplicábitur. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Súscipe, Dómine, múnera, quæ in ejus tibi sollemnitáte deférimus, cujus nos confídimus patrocínio liberári."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joann 21:23"},{"k":"text","la":"Exiit sermo inter fratres, quod discípulus ille non móritur: et non dixit Jesus: Non móritur; sed: Sic eum volo manére, donec véniam."}],"Postcommunio":[{"k":"text","la":"Refécti cibo potúque caelésti, Deus noster, te súpplices deprecámur: ut, in cuius haec commemoratióne percépimus, eius muniémur et précibus."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Oratio":[{"k":"rubric","la":"Pro Octava Nativitatis"},{"k":"text","la":"Concéde, quǽsumus, omnípotens Deus: ut nos Unigéniti tui nova per carnem Natívitas líberet; quos sub peccáti jugo vetústa sérvitus tenet."},{"k":"macro","name":"Per eundem"}],"Commemoratio Secreta":[{"k":"rubric","la":"Pro Octava Nativitatis"},{"k":"text","la":"Obláta, Dómine, múnera, nova Unigéniti tui Nativitáte sanctífica: nosque a peccatórum nostrórum máculis emúnda."},{"k":"macro","name":"Per eundem"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Pro Octava Nativitatis"},{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut natus hódie Salvátor mundi, sicut divínæ nobis generatiónis est auctor; ita et immortalitátis sit ipse largítor:"},{"k":"macro","name":"Qui tecum"}]},"hr":{"e84ce5569ff74d33":{"t":"<i>Pomolimo se</i>.\nCrkvu svoju, Gospodine, dobrostivo rasvijetli, da prosvijetljena učenjem blaženoga Ivana tvoga apostola i evanđeliste dopre do vječnih darova.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"d7ab682642e99d6b":{"t":"Primi, Gospodine, darove što ti ih prinosimo na blagdan onoga po čijem se zagovoru nadamo osloboditi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"965301ed41e77617":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni nebeskom hranom i pićem ponizno te molimo, Bože naš, da nas zaštite molitve onoga u čiji spomen blagovasmo tvoje tajne.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"f17bbac22be741ea":{"t":"Sir 15, 5, Ps 91, 2\n(Sir 15, 5) Usred Crkve otvorio je Gospodin usta njegova i napunio ga duhom mudrosti i razuma, ogrnuo ga odjećom slave. (Ps. 91, 2) Dobro je slaviti Gospodina i pjevati imenu tvojem, Višnji!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 15, 5) Usred Crkve otvorio je Gospodin usta njegova i napunio ga duhom mudrosti i razuma, ogrnuo ga odjećom slave."},"6f5d0df0c8697574":{"t":"Sir 15, 1-6\nČitanje knjige Mudrosti. Tko se boji Boga, činit će dobro. A tko se drži pravde, postići će je i kao časna majka izaći će ona pred njega. Hranit će ga kruhom života i razuma i napajati vodom spasonosne mudrosti. U njemu će se utvrditi i neće kolebati i uzdržat će ga da se ne smete. Uzvisit će ga kod njegovih bližnjih i usred zbora otvorit će mu se usta i napunit će ga duhom mudrosti i razuma i odjenut će ga haljinom slave. Gospodin Bog naš obogatit će ga milinom i radošću i učinit će da mu ime ostane u trajnoj uspomeni."},"84c5af24cfd4cc1a":{"t":"Iv 21, 23 i 22\nPronio se glas među braćom da onaj učenik neće umrijeti. A Isus mu nije rekao: »Neće umrijeti«, nego: Hoću da on ostane tako dok ne dođem. Ti me slijedi.\n\nIv 21, 24\n<i>Aleluja</i>, <i>aleluja</i>.\nOvo je onaj učenik koji svjedoči za ovo, i znamo da je istinito svjedočanstvo njegovo. <i>Aleluja</i>."},"d20b8233595dd738":{"t":"Iv 21, 19-24\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme: reče Isus Petru: »Idi za mnom!« Petar se obazre i ugleda da za njim ide onaj učenik kojega je Isus ljubio i koji je na večeri počinuo na njegovim prsima i upitao: »Gospodine, tko je taj, koji će te izdati?« Kada, dakle, Petar ovoga vidje, upita Isusa: »Gospodine, što će biti s ovim?« Isus mu odgovori : »Hoću da on ostane tako dok ne dođem, što je tebi do toga? Ti idi za mnom!« Pronio se s toga među braćom taj glas da onaj učenik neće umrijeti. A Isus mu nije rekao: »Ne će umrijeti«, nego: »Hoću da on ostane tako, dok ne dođem, što je tebi do toga?« To je onaj učenik, koji svjedoči za ovo što je napisao. I znamo da je istinito svjedočanstvo njegovo."},"26bc9b7e0a4c66c8":{"t":"Ps 91, 13\nPravednik cvate kao palma i raste kao libanski cedar."},"46276ff06c5f858a":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine sveti Oče, svemogući i vječni Bože: jer je po tajni utjelovljene Riječi očima naše duše sinula nova svjetlost tvoga sjaja. Te dok tjelesnim očima spoznajemo Boga, on nas zanosi ljubavlju prema nevidljivim dobrima. I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"e53778661987628e":{"t":"Iv 21, 23\nPronio se glas među braćom da onaj učenik neće umrijeti. A Isus mu nije rekao: Neće umrijeti, nego: Hoću da on ostane tako dok ne dođem."}}});
